            range = o.string("range"),
            price = o.string("price"),
            change = o.string("change"),
            isUp = o.bool("isUp"),
            holding = o.string("holding"),
            history = o.doubles("history"),
            buy = o.list("buy", TradeOption::from),
            sell = o.list("sell", TradeOption::from),
